INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Lagerung von Servern immer teuer ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Dauer und Raum"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element beeinflusst die Kosten bei der Beschaffung von IT-Hardware am meisten?', 3, '[{"text": "Transportkosten", "correct": true, "because": "Hängen von Entfernung ab"}, {"text": "Farbe der Geräte", "correct": false, "because": "Irrelevant für Kosten"}, {"text": "Markenname", "correct": false, "because": "Nur indirekt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren erhöhen die Ausgaben für ein IT-Projekt?', 5, '[{"text": "Lagerhaltung", "correct": true, "because": "Erfordert Platz und Pflege"}, {"text": "Vertriebsaufwand", "correct": true, "because": "Personal und Werbung"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Optional, nicht zwingend"}, {"text": "Bürogestaltung", "correct": false, "because": "Nicht direkt zugeordnet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Beschaffungskosten sind Teil der Betriebskosten. b) Lagerung spart immer Geld.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lagerung verursacht Kosten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich die Kosten für eine Softwareverteilung berechne?', 4, '[{"text": "Lizenzverwaltung", "correct": false, "because": "Verursacht Aufwand"}, {"text": "Supportzeit", "correct": false, "because": "Teil des Vertriebs"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Transportkosten nur bei Hardware anfallen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bei physischen Medien für Software"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme senkt die Ausgaben für die Lagerung von IT-Geräten?', 3, '[{"text": "Just-in-Time-Lieferung", "correct": true, "because": "Reduziert Lagerbedarf"}, {"text": "Größere Lagerhallen", "correct": false, "because": "Erhöht Kosten"}, {"text": "Bunte Regale", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Posten fallen bei der Beschaffung eines Netzwerks an?', 5, '[{"text": "Einkaufspreis", "correct": true, "because": "Basis der Hardwarekosten"}, {"text": "Versandkosten", "correct": true, "because": "Transport zum Standort"}, {"text": "Marketingbudget", "correct": false, "because": "Nicht direkt zugeordnet"}, {"text": "Büromöbel", "correct": false, "because": "Kein Beschaffungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Vertriebskosten nur Personal betreffen und b) Lagerung immer fix ist. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Vertrieb umfasst mehr, Lagerung variabel"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Kosten für eine Serverlieferung zu kalkulieren?', 4, '[{"text": "Transportaufwand", "correct": false, "because": "Teil der Lieferkosten"}, {"text": "Zollgebühren", "correct": false, "because": "Relevant bei Import"}, {"text": "Farbe der Verpackung", "correct": true, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Vertriebskosten immer fix?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Aufwand"}, {"text": "Ja", "correct": false, "because": "Können variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Reduktion der Lagerzeit?', 4, '[{"text": "Geringere Lagerkosten", "correct": true, "because": "Weniger Platzbedarf"}, {"text": "Schnellere Verfügbarkeit", "correct": true, "because": "Kürzere Wartezeiten"}, {"text": "Höhere Anschaffungskosten", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Beschaffungskosten nur den Einkaufspreis umfassen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Transport und Zoll zählen dazu"}, {"text": "Ja", "correct": false, "because": "Mehr als nur Einkauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich den Vertrieb von Software optimiere?', 3, '[{"text": "Kosten senken", "correct": true, "because": "Effizienz erhöhen"}, {"text": "Maximale Lagerung", "correct": false, "because": "Nicht relevant für Software"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Vertriebsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Transportkosten sind variabel. b) Lagerkosten sind immer indirekt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lagerkosten können direkt sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um die Kosten für eine Hardwarelieferung zu senken?', 4, '[{"text": "Rahmenverträge mit Lieferanten", "correct": true, "because": "Reduzieren Transportaufwand"}, {"text": "Maximale Lagerung", "correct": false, "because": "Erhöht Kosten"}, {"text": "Einzelbestellungen", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Vertriebskosten nur für physische Güter anfallen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Software relevant"}, {"text": "Ja", "correct": false, "because": "Umfasst Dienstleistungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen die Lagerung von IT-Komponenten teuer?', 5, '[{"text": "Lange Lagerzeiten", "correct": true, "because": "Erhöhen Mietkosten"}, {"text": "Klimatisierung", "correct": true, "because": "Schützt Geräte, kostet Energie"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Reduziert Lagerung"}, {"text": "Bunte Verpackung", "correct": false, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Beschaffungskosten immer fix?', 2, '[{"text": "Nein", "correct": true, "because": "Variieren mit Menge"}, {"text": "Ja", "correct": false, "because": "Abhängig von Auftrag"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich, um die Vertriebskosten für ein IT-Produkt zu minimieren?', 3, '[{"text": "Digitale Verteilung", "correct": true, "because": "Senkt physischen Aufwand"}, {"text": "Große Lagerhallen", "correct": false, "because": "Erhöht Kosten"}, {"text": "Manuelle Abrechnung", "correct": false, "because": "Ineffizient"}]');
